begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(13);
insert into auth.users(id,email,email_confirmed_at) values('04000000-0000-4000-8000-000000000001','quiz-admin@example.test',now()),('04000000-0000-4000-8000-000000000002','quiz-author@example.test',now()),('04000000-0000-4000-8000-000000000003','quiz-learner@example.test',now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('14000000-0000-4000-8000-000000000001','04000000-0000-4000-8000-000000000001',now(),now()),('14000000-0000-4000-8000-000000000002','04000000-0000-4000-8000-000000000002',now(),now()),('14000000-0000-4000-8000-000000000003','04000000-0000-4000-8000-000000000003',now(),now());
insert into profiles(id,username,display_name,role,policy_version,policy_accepted_at) values('04000000-0000-4000-8000-000000000001','quiz_admin','Admin','admin','2026-11-01',now()),('04000000-0000-4000-8000-000000000002','quiz_author','Author','member','2026-11-01',now()),('04000000-0000-4000-8000-000000000003','quiz_learner','Learner','member','2026-11-01',now());
insert into classes(id,name)values('24000000-0000-4000-8000-000000000001','Quiz test');
update workspace_settings set limits=limits||'{"pending_submissions":1}'::jsonb;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"04000000-0000-4000-8000-000000000002","session_id":"14000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
select lives_ok($$select save_quiz('24000000-0000-4000-8000-000000000001','A practice quiz','manual','{"format_version":1,"questions":[{"id":"q1","type":"true_false","prompt":"True?","points":1,"answer":true}]}','{"shuffle":false,"mode":"paged","page_size":10,"quiz_seconds":null,"question_seconds":null}')$$,'member can create a validated quiz draft');
select throws_ok($$select save_quiz('24000000-0000-4000-8000-000000000001','Bad quiz','manual','{"format_version":1,"questions":[{"id":"q1","type":"multiple_choice","prompt":"Pick","points":1,"options":["A","B"],"answer":9}]}','{"shuffle":false,"mode":"paged","page_size":10,"quiz_seconds":null,"question_seconds":null}')$$,'23514',null,'database rejects invalid answer indices');
select lives_ok($$select submit_quiz((select id from quiz_versions limit 1))$$,'author can submit a draft');
select throws_ok($$select review_quiz(auth.uid(),(select id from quiz_versions limit 1),'published','')$$,'42501',null,'member cannot call admin review function');
reset role;
select lives_ok($$select review_quiz('04000000-0000-4000-8000-000000000001',(select id from quiz_versions limit 1),'published','Ready')$$,'admin review publishes version');
select throws_ok($$update quiz_versions set content=jsonb_set(content,'{questions,0,answer}','false')$$,'23514',null,'published content is immutable');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"04000000-0000-4000-8000-000000000002","session_id":"14000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
select lives_ok($$select save_quiz('24000000-0000-4000-8000-000000000001','Updated quiz','manual','{"format_version":1,"questions":[{"id":"q1","type":"true_false","prompt":"True?","points":1,"answer":false}]}','{"shuffle":false,"mode":"paged","page_size":10,"quiz_seconds":null,"question_seconds":null}',null,(select id from quizzes limit 1))$$,'editing published quiz creates a separate draft');
select is((select count(*)from quiz_versions),2::bigint,'both versions are preserved');
select set_config('request.jwt.claims','{"sub":"04000000-0000-4000-8000-000000000003","session_id":"14000000-0000-4000-8000-000000000003","aal":"aal1"}',true);
select lives_ok($$select record_attempt('64000000-0000-4000-8000-000000000001',(select id from quiz_versions where status='published'),1,1,'{"responses":{"q1":true},"question_ids":["q1"]}',now())$$,'learner can record own published-version attempt');
select lives_ok($$select record_attempt('64000000-0000-4000-8000-000000000001',(select id from quiz_versions where status='published'),0,1,'{}',now())$$,'retry uses the same id without duplicating attempt');
select is((select score from attempts where id='64000000-0000-4000-8000-000000000001'),1::numeric,'retry does not overwrite original score');
reset role;
delete from auth.users where id='04000000-0000-4000-8000-000000000002';
set local role authenticated;
select is((select count(*) from quiz_versions where status='published'),1::bigint,'published quiz survives author account deletion');
select is((select count(*) from attempts),1::bigint,'learner historical attempt survives author leaving');
select * from finish();
rollback;
